impl ToValue for Tree {
    fn to_value_controlled(&self, control: &mut semio_framework_value::NativeEncodeControl<'_>) -> Result<DslValue, ValueError> { native_controlled::encode_tree(self, control) }
    fn to_value(&self) -> DslValue {
