        match owner.close_step(1,grant) {ValueRetirementStep::Pending {released_items,released_bytes}=>{assert!(released_items<=1&&released_bytes<=grant);released+=released_bytes;},ValueRetirementStep::Complete=>{},ValueRetirementStep::Blocked=>panic!("published body/capacity pair blocked at turn {turns}")}
